def add(a, b):
    """Compute add."""
    return a + b

def subtract(a, b):
    """Compute subtract."""
    return a - b

def multiply(a, b):
    """Compute multiply."""
    return a * b

def divide(a, b):
    """Compute divide."""
    return a / b

def minimum(a, b):
    """Compute minimum."""
    return min(a, b)

def maximum(a, b):
    """Compute maximum."""
    return max(a, b)

def clamp(a, lo, hi):
    """Compute clamp."""
    return min(max(a, lo), hi)

def square(a):
    """Compute square."""
    return a * a
